open(lib_path,'w').write('''def find_rect_layers(grid):
    """Find the outer rectangle and innermost solid region of nested rects in a zero background; return (outer, inner, inner_color) bounding boxes and color."""
    h, w = len(grid), len(grid[0])
    cells = [(i, j, grid[i][j]) for i in range(h) for j in range(w) if grid[i][j] != 0]
    if not cells:
        return None
    colors = {c for _, _, c in cells}
    # innermost color = color of smallest region / color whose cells form the core (not enclosing others)
    # outer color = color whose bounding box is largest
    boxes = {}
    for c in colors:
        pts = [(i, j) for i, j, cc in cells if cc == c]
        rs = [p[0] for p in pts]; cs = [p[1] for p in pts]
        boxes[c] = (min(rs), min(cs), max(rs), max(cs))
    outer = max(colors, key=lambda c: (boxes[c][2]-boxes[c][0]+1)*(boxes[c][3]-boxes[c][1]+1))
    inner = min(colors, key=lambda c: (boxes[c][2]-boxes[c][0]+1)*(boxes[c][3]-boxes[c][1]+1))
    return boxes[outer], boxes[inner], inner

def expand_inner_color_ring(grid):
    """Fill background (0) cells in a box expanded from the outer rect by a ring whose thickness equals the inner square's side (min inner dim, minus 1 if the inner region is non-square), keeping the original shape."""
    res = [row[:] for row in grid]
    info = find_rect_layers(grid)
    if info is None:
        return res
    (r0, c0, r1, c1), (_, _, _), color = info[0], info[1], info[2]
    ih = info[1][2] - info[1][0] + 1
    iw = info[1][3] - info[1][1] + 1
    t = min(ih, iw) - (1 if ih != iw else 0)
    a, b, c, d = r0 - t, c0 - t, r1 + t, c1 + t
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 0 and a <= i <= c and b <= j <= d:
                res[i][j] = color
    return res

def transform(grid):
    """task-042aed5a: expand inner color ring around nested rectangles."""
    return expand_inner_color_ring(grid)
